import{_ as a,o as t,c as n,a0 as o}from"./chunks/framework.CNDWyMYS.js";const u=JSON.parse('{"title":"Paths and external dependencies","description":"","frontmatter":{},"headers":[],"relativePath":"paths_and_external_dependencies.md","filePath":"paths_and_external_dependencies.md"}'),s={name:"paths_and_external_dependencies.md"};function r(i,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="paths-and-external-dependencies" tabindex="-1">Paths and external dependencies <a class="header-anchor" href="#paths-and-external-dependencies" aria-label="Permalink to &quot;Paths and external dependencies&quot;">​</a></h1><p>Many Lua rocks are bindings to C libraries: for example, <a href="https://luarocks.org/modules/daurnimator/luaossl" target="_blank" rel="noreferrer">luaossl</a> is a binding library to the <a href="https://openssl.org" target="_blank" rel="noreferrer">OpenSSL</a> library. This means that, in our example, luaossl <em>depends on</em> OpenSSL. But since this is not a regular rock-to-rock dependency (if it were, LuaRocks could solve this by itself), we call this an <strong>external dependency</strong>.</p><p>When building a rock with external dependencies, LuaRocks needs to make sure the necessary C libraries and headers are installed, and know where those C libraries are.</p><h2 id="specifying-external-dependencies-in-your-rockspecs" tabindex="-1">Specifying external dependencies in your rockspecs <a class="header-anchor" href="#specifying-external-dependencies-in-your-rockspecs" aria-label="Permalink to &quot;Specifying external dependencies in your rockspecs&quot;">​</a></h2><p>When writing a rock with external dependencies, one needs to be careful to avoid the &quot;works on my machine&quot; situation: when you write code that hardcodes the location of external dependencies as they are in your system, but then fails to build in other people&#39;s systems.</p><p>The way to avoid this problem is to avoid any hardcoded paths. Instead, the <code>build</code> section of a <a href="./rockspec_format.html">rockspec</a> should make use of path variables. If not using the <code>builtin</code> build type, paths set by the module&#39;s own build system must not be relied on and explicit paths should be passed to it by the rockspec instead.</p><p>Paths where LuaRocks should install files into are defined as the <code>PREFIX</code>, <code>LUADIR</code>, <code>LIBDIR</code> and <code>BINDIR</code> variables. (See the <a href="./config_file_format.html">Config file format</a> page for details.)</p><p>Paths for external dependencies (such as C libraries used in the compilation of modules) are generated from the <code>external_dependencies</code> section of the rockspec (see the <a href="./rockspec_format.html">Rockspec format</a> page for details.) Lua itself is considered a special external dependency.</p><p>These path variables are set in the global <code>variables</code> table defined in the <a href="./config_file_format.html">config file</a>. Their values are populated automatically by LuaRocks, but can be overriden by the user (either by setting them directly in the config file, or by passing them through the &quot;luarocks&quot; command line).</p><p>The <code>variables</code> table always contains entries for <code>LUA_BINDIR</code>, <code>LUA_INCDIR</code> and <code>LUA_LIBDIR</code>. Like the other external dependency variables, these can be overriden in the LuaRocks config file or in the command line.</p>',10)])])}const f=a(s,[["render",r]]);export{u as __pageData,f as default};
